import { getImage } from 'astro:assets';
import { getEntry } from 'astro:content';
import { slugOf } from '../i18n';
import type { Post } from './posts';

/**
 * A post's share image: its cover, or the card generated by src/pages/og/[...route].ts. Translations use their
 * original's image, because the card font has no Chinese or Japanese glyphs.
 */
export async function postImage(post: Post): Promise<string> {
  const original = (await getEntry('posts', slugOf(post.id))) ?? post;
  return original.data.cover
    ? (await getImage({ src: original.data.cover, width: 1200, height: 630, fit: 'cover', format: 'jpg' })).src
    : `/og/${slugOf(post.id)}.png`;
}
